const raw = $('Webhook').first().json.body;
const { bucket_file_ids, message } = raw;
const current_date = new Date().toISOString().split('T')[0];
const github_owner = 'blasvicco';
const github_repo = 'da-sapot-processes';
const github_tag = 'main';
const language = raw.session?.language || 'es';
const data = { ...raw, current_date, github_owner, github_repo, github_tag, language };
const ref = github_tag;
const fileList = (bucket_file_ids || [])
  .map((id) => `- bucket_file_id: ${id}`)
  .join('\n');
const schemaReference = `Every item's payload MUST follow this exact structure and field names — do not invent your own, do not flatten the line items into the header, and omit (don't invent a value for) any field you can't find in the source data:
{
  "Supplier": "",
  "DocDate": "YYYY-MM-DD",
  "RequriedDate": "YYYY-MM-DD",
  "Comments": "",
  "items": [
    {
      "ItemCode": "...",
      "Quantity": 0,
      "UnitPrice": 0,
      "LineVendor": "...",
      "TaxCode": "...",
      "WarehouseCode": "...",
      "UomCode": "...",
      "ShipDate": "YYYY-MM-DD",
      "CostingCode": "...",
      "CostingCode2": "..."
    }
  ]
}\n`;
const chatInput = `Today: ${current_date}. Respond in: ${language}.\n\nFor each DISTINCT kind of record you identify (e.g. "Purchase Request"), call get_file_contents with owner=${github_owner}, repo=${github_repo}, path={organization.target}/index.json, ref=${ref} (resolve {organization.target} from organization.target in the INPUT JSON below) to find its process-index entry, and copy that entry's exact "path" value into the "path" field of every item of that kind. Only do this lookup once per distinct process type, not once per item.\n\n${schemaReference}\nUser message: "${message}"\n\nAttached files (call Read Bucket File once per id to get its content):\n${fileList}\n\nINPUT:\n\`\`\`json\n${JSON.stringify(data, null, 2)}\n\`\`\`\n\nDetermine how many purchase requests this describes in total across ALL attached files and/or the message text itself (a file's rows are not automatically 1 request each — look at the actual content structure), extract each one's field values into the exact payload shape above, resolve each item's "path" as instructed, and return the structured items array.`;
return [{ json: { chatInput } }];
